// Webhook gövdesinden tablo satırını kurar ve tahmini hazırlanma süresini hesaplar.
// Süre kuralla hesaplanır, AI'a hazır verilir: modelin kendi kafasından teslim sözü vermesini istemiyoruz.
// Kategori eşlemesi src/data/products.js ile aynı olmalı; yeni ürün eklenince burayı da güncelleyin.
const CATEGORY_BY_PRODUCT = {
  'hus-kuksa': 'kuksa',
  'ceviz-yemek-kasigi': 'kasik',
  'kiraz-olcu-kasigi': 'kasik',
}
// İş günü: ilk ürün için taban süre, her ek adet için ek süre.
const PREP_RULES = {
  kuksa: { base: 5, perExtra: 2 },
  kasik: { base: 3, perExtra: 1 },
}
const DEFAULT_RULE = { base: 5, perExtra: 2 }
const MAX_DAYS = 21

return $input.all().map(item => {
  const order = item.json.body
  const quantity = Number(order.quantity) || 1
  const rule = PREP_RULES[CATEGORY_BY_PRODUCT[order.productId]] || DEFAULT_RULE
  const prepDays = Math.min(MAX_DAYS, rule.base + rule.perExtra * (quantity - 1))

  return {
    json: {
      'Tarih': new Date().toLocaleString('tr-TR', { timeZone: 'Europe/Istanbul' }),
      'Ad': order.name,
      'Ürün Kodu': order.productId,
      'Ürün': order.productName,
      'Adet': quantity,
      'Telefon': order.phone,
      'E-posta': order.email,
      'Hazırlanma (iş günü)': prepDays,
    },
  }
})

